window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fbffa710d0cfd0c2"]={"versions": [{"id": "FIG-fbffa710d0cfd0c2", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>, formal als <code>sm UdpNmAlgorithm</code> bezeichnet).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb.</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>[Network Requested]</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>[Network Released]</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_Init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Guards <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus-Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_Init()</code>, <code>Nm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode()</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>, <code>Nm_NetworkTimeoutException()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdIfRxIndication()</code>, <code>UdpNm_SoAdIfTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>UdpNm_RepeatMessageBitIndication()</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_Init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>Nm_PassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest()</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdIfRxIndication()</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdIfRxIndication()</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdIfTxConfirmation()</code>) setzt den <code>NM-Timeout Timer</code> zurück.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> hier ab, wird er zyklisch neu gestartet (Monitoring-Toleranz).</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>[Network Requested]</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>[Network Released]</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs; Rx- und Tx-Bestätigungen re-triggern den <code>NM-Timeout Timer</code>.</li>\n<li>Tritt ein Timeout auf (<code>NM-Timeout Timer has expired</code>), wird er neu gestartet und <code>Nm_NetworkTimeoutException()</code> ausgelöst (Erkennung von Kommunikationsabrissen/Fehlern).</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Ausführung von <code>/ Stop Bus Load Reduction</code> $\\rightarrow$ Wechsel nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr; Rx- und Tx-Ereignisse re-triggern den <code>NM-Timeout Timer</code>.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>), erfolgt der direkte Wechsel zurück in den <code>Normal Operation State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> erzwingen <code>UdpNm_RepeatMessageBitIndication()</code> (Remote-Node fordert Synchronisation an) oder <code>UdpNm_RepeatMessageRequest()</code> (lokale Anforderung) den sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus-Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode()</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus-Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdIfRxIndication()</code> oder <code>UdpNm_NetworkRequest()</code> bricht die Phase ab und führt unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um fehlerhafte <code>Nm_NetworkTimeoutException()</code>-Aufrufe oder ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>UdpNmWaitBusSleepTime</code> (<code>Wait Bus-Sleep Timer</code>): Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdIfRxIndication()</code> und <code>UdpNm_SoAdIfTxConfirmation()</code> werden aus dem Interrupt- oder Task-Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte (<code>SchM_Enter_UdpNm_*</code>) abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n<li>Das Auslösen von <code>Nm_NetworkTimeoutException()</code> im <code>Normal Operation State</code> ist ein Indikator für fehlende Tx-Bestätigungen (z. B. Socket-Puffer voll / SoAd-Übertragungsfehler) oder ausbleibende Rx-PDUs. Treiber-/Stack-Entwickler müssen hier Diagnoseroutinen (DEM/DET) ankoppeln.</li>\n</ul>"}, {"id": "FIG-afc6d8a47ae3fd41", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb.</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>Network Requested</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>Network Released</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Bedingungen <code>Network Requested</code> und <code>Network Released</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_init()</code>, <code>NmPassiveStartUp()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMesageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode()</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>, <code>Nm_TxTimeoutException()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>NmPassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest();</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication()</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication()</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation()</code>) setzt den <code>NM-Timeout Timer</code> zurück.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> hier ab, wird er über einen Selbstübergang zyklisch neu gestartet.</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>Network Requested</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>Network Released</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs; Rx- und Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>) re-triggern den <code>NM-Timeout Timer</code>.</li>\n<li>Tritt ein Timeout auf (<code>NM-Timeout Timer has expired</code>), wird er neu gestartet und <code>Nm_TxTimeoutException()</code> ausgelöst.</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Direkter Wechsel nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr; Rx- und Tx-Ereignisse (<code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>) re-triggern den <code>NM-Timeout Timer</code>.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>), erfolgt der direkte Wechsel zurück in den <code>Normal Operation State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMesageRequest()</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode()</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication()</code> oder Aufruf von <code>UdpNm_PassiveStartUp()</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um fehlerhafte <code>Nm_TxTimeoutException()</code>-Aufrufe oder ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>UdpNmWaitBusSleepTime</code> (<code>Wait Bus Sleep Timer</code>): Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Interrupt- oder Task-Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n<li>Das Auslösen von <code>Nm_TxTimeoutException()</code> im <code>Normal Operation State</code> signalisiert das Ausbleiben erwarteter Tx-Bestätigungen (z. B. Socket-Puffer voll / SoAd-Übertragungsfehler) oder Timeouts bei der PDU-Übertragung. Stack-Entwickler müssen hier Diagnoseroutinen (DEM/DET) ankoppeln.</li>\n</ul>"}, {"id": "FIG-039fd763d5e04e0e", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb.</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>Network Requested</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>Network Released</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Bedingungen <code>Network Requested</code> und <code>Network Released</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_init()</code>, <code>NmPassiveStartUp()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMesageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode()</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>, <code>Nm_TxTimeoutException()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>NmPassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest();</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication()</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication()</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation()</code>) setzt den <code>NM-Timeout Timer</code> zurück.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> hier ab, wird er über einen Selbstübergang zyklisch neu gestartet.</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>Network Requested</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>Network Released</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs; Rx- und Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>) re-triggern den <code>NM-Timeout Timer</code>.</li>\n<li>Tritt ein Timeout auf (<code>NM-Timeout Timer has expired</code>), wird er neu gestartet und <code>Nm_TxTimeoutException()</code> ausgelöst.</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Direkter Wechsel nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr; Rx- und Tx-Ereignisse (<code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>) re-triggern den <code>NM-Timeout Timer</code>.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>), erfolgt der direkte Wechsel zurück in den <code>Normal Operation State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMesageRequest()</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode()</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication()</code> oder Aufruf von <code>UdpNm_PassiveStartUp()</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um fehlerhafte <code>Nm_TxTimeoutException()</code>-Aufrufe oder ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>UdpNmWaitBusSleepTime</code> (<code>Wait Bus Sleep Timer</code>): Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Interrupt- oder Task-Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n<li><strong>Fehlerbehandlung:</strong></li>\n<li>Das Auslösen von <code>Nm_TxTimeoutException()</code> im <code>Normal Operation State</code> signalisiert das Ausbleiben erwarteter Tx-Bestätigungen (z. B. Socket-Puffer voll / SoAd-Übertragungsfehler) oder Timeouts bei der PDU-Übertragung. Stack-Entwickler müssen hier Diagnoseroutinen (DEM/DET) ankoppeln.</li>\n</ul>"}, {"id": "FIG-ae3782d68d2b2cf2", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb mit übergeordneten Selbstübergängen für Rx/Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_SoAdTxConfirmation();</code>).</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>[Network Requested]</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>[Network Released]</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_Init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Guards <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>UdpNmPnHandleMultipleNetworkRequests</code>: Steuert das Verhalten bei wiederholter Netzanforderung im <code>Ready Sleep State</code> (Partial Networking).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_Init()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode();</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_Init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>UdpNm_PassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest()</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication();</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong>Globale Ereignisse im <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication();</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation();</code>) auf Ebene des Verbundzustands setzt den <code>NM-Timeout Timer</code> zurück (<code>/ Start NM-Timeout Timer;</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>NM-Timeout Timer</code> ab, wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>[Network Requested]</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>[Network Released]</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> ab (<code>NM-Timeout Timer has expired</code>), wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>):</li>\n<li>Bei deaktivierter Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == FALSE]</code>): Direkter Übergang in den <code>Normal Operation State</code>.</li>\n<li>Bei aktiver Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == TRUE]</code>): Übergang in den <code>Repeat Message State</code> unter Ausführung von <code>/ Start Repeat Message Timer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMessageRequest();</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus-Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode();</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_PassiveStartUp();</code> oder <code>UdpNm_NetworkRequest();</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>Wait Bus Sleep Timer</code>: Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li>*<em>Teilnetzwerk-Konfiguration (</em>Partial Networking<em>):</em>*</li>\n<li>Der Parameter <code>UdpNmPnHandleMultipleNetworkRequests</code> steuert das Wiederaufwach- bzw. Re-Synchronisationsverhalten: Bei <code>TRUE</code> erzwingt eine erneute lokale Netzanforderung im Bereitschaftszustand (<code>Ready Sleep State</code>) den Wechsel in den <code>Repeat Message State</code>, um andere Knoten über die erneute Busanforderung aktiv zu synchronisieren; bei <code>FALSE</code> reicht der direkte interne Wechsel in den <code>Normal Operation State</code>.</li>\n<li><strong>Architektur der Rx/Tx-Bestätigungen:</strong></li>\n<li>Das Rücksetzen des <code>NM-Timeout Timer</code> durch <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> ist auf der Ebene des Verbundzustands <code>Network Mode</code> modelliert und gilt daher einheitlich über alle Subzustände hinweg, ohne redundante Transitionen in den Einzelzuständen.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n</ul>"}, {"id": "FIG-4403c20b3e0fe5cb", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb mit übergeordneten Selbstübergängen für Rx/Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_SoAdTxConfirmation();</code>).</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>[Network Requested]</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>[Network Released]</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_Init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Guards <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>UdpNmPnHandleMultipleNetworkRequests</code>: Steuert das Verhalten bei wiederholter Netzanforderung im <code>Ready Sleep State</code> (Partial Networking).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_Init()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode();</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_Init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>UdpNm_PassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest()</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication();</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong>Globale Ereignisse im <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication();</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation();</code>) auf Ebene des Verbundzustands setzt den <code>NM-Timeout Timer</code> zurück (<code>/ Start NM-Timeout Timer;</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>NM-Timeout Timer</code> ab, wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>[Network Requested]</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>[Network Released]</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> ab (<code>NM-Timeout Timer has expired</code>), wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>):</li>\n<li>Bei deaktivierter Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == FALSE]</code>): Direkter Übergang in den <code>Normal Operation State</code>.</li>\n<li>Bei aktiver Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == TRUE]</code>): Übergang in den <code>Repeat Message State</code> unter Ausführung von <code>/ Start Repeat Message Timer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMessageRequest();</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus-Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode();</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_PassiveStartUp();</code> oder <code>UdpNm_NetworkRequest();</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>Wait Bus Sleep Timer</code>: Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li>*<em>Teilnetzwerk-Konfiguration (</em>Partial Networking<em>):</em>*</li>\n<li>Der Parameter <code>UdpNmPnHandleMultipleNetworkRequests</code> steuert das Wiederaufwach- bzw. Re-Synchronisationsverhalten: Bei <code>TRUE</code> erzwingt eine erneute lokale Netzanforderung im Bereitschaftszustand (<code>Ready Sleep State</code>) den Wechsel in den <code>Repeat Message State</code>, um andere Knoten über die erneute Busanforderung aktiv zu synchronisieren; bei <code>FALSE</code> reicht der direkte interne Wechsel in den <code>Normal Operation State</code>.</li>\n<li><strong>Architektur der Rx/Tx-Bestätigungen:</strong></li>\n<li>Das Rücksetzen des <code>NM-Timeout Timer</code> durch <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> ist auf der Ebene des Verbundzustands <code>Network Mode</code> modelliert und gilt daher einheitlich über alle Subzustände hinweg, ohne redundante Transitionen in den Einzelzuständen.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n</ul>"}, {"id": "FIG-1b07fbfb3c72d06d", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb mit übergeordneten Selbstübergängen für Rx/Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_SoAdTxConfirmation();</code>).</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>[Network Requested]</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>[Network Released]</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_Init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Guards <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>UdpNmPnHandleMultipleNetworkRequests</code>: Steuert das Verhalten bei wiederholter Netzanforderung im <code>Ready Sleep State</code> (Partial Networking).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_Init()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode();</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_Init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>UdpNm_PassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest()</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication();</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong>Globale Ereignisse im <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication();</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation();</code>) auf Ebene des Verbundzustands setzt den <code>NM-Timeout Timer</code> zurück (<code>/ Start NM-Timeout Timer;</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>NM-Timeout Timer</code> ab, wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>[Network Requested]</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>[Network Released]</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> ab (<code>NM-Timeout Timer has expired</code>), wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>):</li>\n<li>Bei deaktivierter Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == FALSE]</code>): Direkter Übergang in den <code>Normal Operation State</code>.</li>\n<li>Bei aktiver Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == TRUE]</code>): Übergang in den <code>Repeat Message State</code> unter Ausführung von <code>/ Start Repeat Message Timer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMessageRequest();</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus-Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode();</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_PassiveStartUp();</code> oder <code>UdpNm_NetworkRequest();</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>Wait Bus Sleep Timer</code>: Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li>*<em>Teilnetzwerk-Konfiguration (</em>Partial Networking<em>):</em>*</li>\n<li>Der Parameter <code>UdpNmPnHandleMultipleNetworkRequests</code> steuert das Wiederaufwach- bzw. Re-Synchronisationsverhalten: Bei <code>TRUE</code> erzwingt eine erneute lokale Netzanforderung im Bereitschaftszustand (<code>Ready Sleep State</code>) den Wechsel in den <code>Repeat Message State</code>, um andere Knoten über die erneute Busanforderung aktiv zu synchronisieren; bei <code>FALSE</code> reicht der direkte interne Wechsel in den <code>Normal Operation State</code>.</li>\n<li><strong>Architektur der Rx/Tx-Bestätigungen:</strong></li>\n<li>Das Rücksetzen des <code>NM-Timeout Timer</code> durch <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> ist auf der Ebene des Verbundzustands <code>Network Mode</code> modelliert und gilt daher einheitlich über alle Subzustände hinweg, ohne redundante Transitionen in den Einzelzuständen.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n</ul>"}, {"id": "FIG-ec43309552dc9546", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb mit übergeordneten Selbstübergängen für Rx/Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_SoAdTxConfirmation();</code>).</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>[Network Requested]</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>[Network Released]</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_Init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Guards <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>UdpNmPnHandleMultipleNetworkRequests</code>: Steuert das Verhalten bei wiederholter Netzanforderung im <code>Ready Sleep State</code> (Partial Networking).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_Init()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode();</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_Init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>UdpNm_PassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest()</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication();</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong>Globale Ereignisse im <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication();</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation();</code>) auf Ebene des Verbundzustands setzt den <code>NM-Timeout Timer</code> zurück (<code>/ Start NM-Timeout Timer;</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>NM-Timeout Timer</code> ab, wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>[Network Requested]</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>[Network Released]</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> ab (<code>NM-Timeout Timer has expired</code>), wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>):</li>\n<li>Bei deaktivierter Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == FALSE]</code>): Direkter Übergang in den <code>Normal Operation State</code>.</li>\n<li>Bei aktiver Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == TRUE]</code>): Übergang in den <code>Repeat Message State</code> unter Ausführung von <code>/ Start Repeat Message Timer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMessageRequest();</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus-Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode();</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_PassiveStartUp();</code> oder <code>UdpNm_NetworkRequest();</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>Wait Bus Sleep Timer</code>: Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li>*<em>Teilnetzwerk-Konfiguration (</em>Partial Networking<em>):</em>*</li>\n<li>Der Parameter <code>UdpNmPnHandleMultipleNetworkRequests</code> steuert das Wiederaufwach- bzw. Re-Synchronisationsverhalten: Bei <code>TRUE</code> erzwingt eine erneute lokale Netzanforderung im Bereitschaftszustand (<code>Ready Sleep State</code>) den Wechsel in den <code>Repeat Message State</code>, um andere Knoten über die erneute Busanforderung aktiv zu synchronisieren; bei <code>FALSE</code> reicht der direkte interne Wechsel in den <code>Normal Operation State</code>.</li>\n<li><strong>Architektur der Rx/Tx-Bestätigungen:</strong></li>\n<li>Das Rücksetzen des <code>NM-Timeout Timer</code> durch <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> ist auf der Ebene des Verbundzustands <code>Network Mode</code> modelliert und gilt daher einheitlich über alle Subzustände hinweg, ohne redundante Transitionen in den Einzelzuständen.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n</ul>"}, {"id": "FIG-e4155a3758322b78", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb mit übergeordneten Selbstübergängen für Rx/Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_SoAdTxConfirmation();</code>).</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>[Network Requested]</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>[Network Released]</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_Init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Guards <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>UdpNmPnHandleMultipleNetworkRequests</code>: Steuert das Verhalten bei wiederholter Netzanforderung im <code>Ready Sleep State</code> (Partial Networking).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_Init()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode();</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_Init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>UdpNm_PassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest()</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication();</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong>Globale Ereignisse im <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication();</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation();</code>) auf Ebene des Verbundzustands setzt den <code>NM-Timeout Timer</code> zurück (<code>/ Start NM-Timeout Timer;</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>NM-Timeout Timer</code> ab, wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>[Network Requested]</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>[Network Released]</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> ab (<code>NM-Timeout Timer has expired</code>), wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>):</li>\n<li>Bei deaktivierter Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == FALSE]</code>): Direkter Übergang in den <code>Normal Operation State</code>.</li>\n<li>Bei aktiver Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == TRUE]</code>): Übergang in den <code>Repeat Message State</code> unter Ausführung von <code>/ Start Repeat Message Timer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMessageRequest();</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus-Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode();</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_PassiveStartUp();</code> oder <code>UdpNm_NetworkRequest();</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>Wait Bus Sleep Timer</code>: Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li>*<em>Teilnetzwerk-Konfiguration (</em>Partial Networking<em>):</em>*</li>\n<li>Der Parameter <code>UdpNmPnHandleMultipleNetworkRequests</code> steuert das Wiederaufwach- bzw. Re-Synchronisationsverhalten: Bei <code>TRUE</code> erzwingt eine erneute lokale Netzanforderung im Bereitschaftszustand (<code>Ready Sleep State</code>) den Wechsel in den <code>Repeat Message State</code>, um andere Knoten über die erneute Busanforderung aktiv zu synchronisieren; bei <code>FALSE</code> reicht der direkte interne Wechsel in den <code>Normal Operation State</code>.</li>\n<li><strong>Architektur der Rx/Tx-Bestätigungen:</strong></li>\n<li>Das Rücksetzen des <code>NM-Timeout Timer</code> durch <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> ist auf der Ebene des Verbundzustands <code>Network Mode</code> modelliert und gilt daher einheitlich über alle Subzustände hinweg, ohne redundante Transitionen in den Einzelzuständen.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n</ul>"}, {"id": "FIG-44a9ba5521a9425f", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>UML State Machine Diagram</em>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Zustands- und Betriebsmodus-Algorithmus des AUTOSAR Classic UDP Network Management (<code>UdpNm</code>) im Kommunikations-Stack (Services Layer).</li>\n<li><strong>Systemkontext:</strong> <code>UdpNm</code> realisiert ein dezentrales, direktes Netzwerkmanagement über Ethernet (UDP/IP). Es synchronisiert die Betriebsmodi des lokalen Steuergeräts (Cluster-Teilnehmer) bezüglich der Netzwerkverfügbarkeit zwischen der generischen Schnittstelle <code>Nm</code> (oberhalb) und dem Socket-Adaptor <code>SoAd</code> (unterhalb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände und Modi:</strong></li>\n<li><strong>Top-Level-Zustände:</strong></li>\n<li><code>Bus-Sleep Mode</code>: Ruhezustand (keine NM-Nachrichten gesendet/empfangen, Bus im Ruhezustand).</li>\n<li><code>Prepare Bus-Sleep Mode</code>: Übergangszustand zur Vorbereitung des Ruhezustands (Busaktivität abgeflaut).</li>\n<li><code>Network Mode</code>: Hierarchischer Verbundzustand (<em>Composite State</em>) für den aktiven Netzwerkbetrieb mit übergeordneten Selbstübergängen für Rx/Tx-Bestätigungen (<code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_SoAdTxConfirmation();</code>).</li>\n<li><strong>Subzustände des <code>Network Mode</code>:</strong></li>\n<li><code>Repeat Message State</code>: Initialer Zustand bei Netzanforderung/Aufwachen; sichert die Erkennbarkeit und Synchronisation aller Netzwerkknoten durch deterministisches Senden/Empfangen von NM-PDUs.</li>\n<li><code>Normal Operation State</code>: Regulärer aktiver Zustand bei bestehender lokaler Netzanforderung (<code>[Network Requested]</code>).</li>\n<li><code>Ready Sleep State</code>: Passiver Bereitschaftszustand bei freigegebenem lokalem Netzwerk (<code>[Network Released]</code>); wartet auf das Einschlafen des Clusters.</li>\n<li><strong>Pseudozustände:</strong></li>\n<li>Initialzustände / <code>PowerOff</code>: Eintritt über <code>UdpNm_Init()</code>.</li>\n<li>Endzustand: <code>PowerOff</code> aus <code>Bus-Sleep Mode</code>.</li>\n<li><em>Junction / Choice Pseudo-States</em>: Eintrittsknoten in den <code>Network Mode</code> sowie Entscheidungsknoten <code>Repeat Message</code> zur Verzweigung anhand der Guards <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Timer (Zustandsvariablen):</strong></li>\n<li><code>NM-Timeout Timer</code>: Überwacht die Zeitspanne zwischen gültigen NM-PDUs (Rx/Tx).</li>\n<li><code>Repeat Message Timer</code>: Steuert die Verweildauer im <code>Repeat Message State</code>.</li>\n<li><code>Wait Bus Sleep Timer</code>: Verzögerungszeit im <code>Prepare Bus-Sleep Mode</code> vor dem endgültigen Übergang nach <code>Bus-Sleep Mode</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsparameter:</strong></li>\n<li><code>UdpNmPnHandleMultipleNetworkRequests</code>: Steuert das Verhalten bei wiederholter Netzanforderung im <code>Ready Sleep State</code> (Partial Networking).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Interaktionspartner:</strong></li>\n<li><strong>Service-APIs (von <code>Nm</code> aufgerufen):</strong> <code>UdpNm_Init()</code>, <code>UdpNm_PassiveStartUp()</code>, <code>UdpNm_NetworkRequest()</code>, <code>UdpNm_NetworkRelease()</code>, <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li><strong>Callback-APIs (zu <code>Nm</code> hin):</strong> <code>Nm_NetworkMode()</code>, <code>Nm_PrepareBusSleepMode();</code>, <code>Nm_BusSleepMode()</code>, <code>Nm_NetworkStartIndication()</code>.</li>\n<li><strong>Untere Schicht (<code>SoAd</code> Callbacks):</strong> <code>UdpNm_SoAdRxIndication()</code>, <code>UdpNm_SoAdTxConfirmation()</code>.</li>\n<li><strong>Protokolleigene Indikationen:</strong> <code>Repeat Message Bit Received</code> (Erkennung des gesetzten Repeat-Message-Bits in empfangenen NM-Paketen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Initialisierung & Aufweckphase</p>\n<ol class=\"fig-list\">\n<li><strong>Power-On:</strong> Nach Kaltstart führt <code>UdpNm_Init() / Initialization of UdpNm</code> direkt in den <code>Bus-Sleep Mode</code>.</li>\n<li><strong>Aufwecken aus <code>Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Passiver Start:</em> <code>UdpNm_PassiveStartUp()</code> leitet über den Einstiegsknoten in den <code>Network Mode</code> über.</li>\n<li><em>Aktive Anforderung:</em> <code>UdpNm_NetworkRequest()</code> leitet ebenfalls über den Einstiegsknoten in den <code>Network Mode</code>.</li>\n<li><em>Externes Aufwecken (Rx):</em> Trifft eine NM-PDU ein (<code>UdpNm_SoAdRxIndication();</code>), meldet <code>UdpNm</code> via <code>Nm_NetworkStartIndication()</code> den Aufweckvorgang (bleibt bis zum Moduswechsel im <code>Bus-Sleep Mode</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eintritt in <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start von <code>NM-Timeout Timer</code> und <code>Repeat Message Timer</code>, Aufruf von <code>Nm_NetworkMode()</code>.</li>\n<li>Zielzustand: <code>Repeat Message State</code>.</li>\n</ul>\n<p class=\"fig-p\">#### B. Verhalten im <code>Network Mode</code></p>\n<ol class=\"fig-list\">\n<li><strong>Globale Ereignisse im <code>Network Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Jeder PDU-Empfang (<code>UdpNm_SoAdRxIndication();</code>) oder Sende-Bestätigung (<code>UdpNm_SoAdTxConfirmation();</code>) auf Ebene des Verbundzustands setzt den <code>NM-Timeout Timer</code> zurück (<code>/ Start NM-Timeout Timer;</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>NM-Timeout Timer</code> ab, wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Ablauf des <code>Repeat Message Timer</code>: Übergang auf den Choice-Knoten <code>Repeat Message</code>:</li>\n<li>Ist die lokale Netzanforderung aktiv (<code>[Network Requested]</code>) $\\rightarrow$ Übergang nach <code>Normal Operation State</code>.</li>\n<li>Ist das Netzwerk freigegeben (<code>[Network Released]</code>) $\\rightarrow$ Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Normal Operation State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zyklisches Senden von NM-PDUs.</li>\n<li>Läuft der <code>NM-Timeout Timer</code> ab (<code>NM-Timeout Timer has expired</code>), wird er über einen lokalen Selbstübergang neu gestartet (<code>/ Start NM-Timeout Timer;</code>).</li>\n<li>Bei Freigabe des Netzwerks (<code>UdpNm_NetworkRelease()</code>): Übergang nach <code>Ready Sleep State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong><code>Ready Sleep State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Knoten sendet keine eigenen NM-PDUs mehr.</li>\n<li>Fordert die Applikation das Netzwerk erneut an (<code>UdpNm_NetworkRequest()</code>):</li>\n<li>Bei deaktivierter Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == FALSE]</code>): Direkter Übergang in den <code>Normal Operation State</code>.</li>\n<li>Bei aktiver Mehrfachanforderungs-Behandlung (<code>[UdpNmPnHandleMultipleNetworkRequests == TRUE]</code>): Übergang in den <code>Repeat Message State</code> unter Ausführung von <code>/ Start Repeat Message Timer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiedereintritt in den <code>Repeat Message State</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>Normal Operation State</code> oder <code>Ready Sleep State</code> führen <code>Repeat Message Bit Received</code> oder <code>UdpNm_RepeatMessageRequest();</code> zum sofortigen Wechsel zurück in den <code>Repeat Message State</code> unter Neustart des <code>Repeat Message Timer</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Einschlafsequenz (Shutdown)</p>\n<ol class=\"fig-list\">\n<li>Bleibt im <code>Ready Sleep State</code> der Netzwerkverkehr aus und läuft der <code>NM-Timeout Timer</code> ab:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aktionen: Start des <code>Wait Bus-Sleep Timer</code>, Benachrichtigung <code>Nm_PrepareBusSleepMode();</code>.</li>\n<li>Zielzustand: <code>Prepare Bus-Sleep Mode</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Im <code>Prepare Bus-Sleep Mode</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Läuft der <code>Wait Bus Sleep Timer</code> regulär ab $\\rightarrow$ Aufruf von <code>Nm_BusSleepMode()</code>, Wechsel in den <code>Bus-Sleep Mode</code>.</li>\n<li><em>Abbruch/Wiederaufwachen:</em> Eintreffen von <code>UdpNm_SoAdRxIndication();</code>, <code>UdpNm_PassiveStartUp();</code> oder <code>UdpNm_NetworkRequest();</code> bricht die Phase ab und führt über den Einstiegsknoten unter Neustart der Timer und Aufruf von <code>Nm_NetworkMode()</code> direkt zurück in den <code>Repeat Message State</code> des <code>Network Mode</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Timer-Parametrierung (Konfigurationsvertrag):</strong></li>\n<li><code>UdpNmTimeoutTime</code> (<code>NM-Timeout Timer</code>): Muss strikt größer als die zyklische Sendezeit <code>UdpNmMsgCycleTime</code> zzgl. Jitter ausgelegt sein, um ungewolltes Einschlafen im <code>Ready Sleep State</code> zu verhindern.</li>\n<li><code>UdpNmRepeatMessageTime</code> (<code>Repeat Message Timer</code>): Bestimmt die Mindestdauer, in der alle Teilnehmer synchronisiert wach bleiben. Zu kurze Werte gefährden die globale Netzwerkknoten-Erkennung (<em>Node Detection</em>).</li>\n<li><code>Wait Bus Sleep Timer</code>: Stellt sicher, dass verzögerte Ethernet-Frames im Socket-Layer abgefangen werden, bevor Transceiver/Controller in Low-Power-Modi versetzt werden.</li>\n<li>*<em>Teilnetzwerk-Konfiguration (</em>Partial Networking<em>):</em>*</li>\n<li>Der Parameter <code>UdpNmPnHandleMultipleNetworkRequests</code> steuert das Wiederaufwach- bzw. Re-Synchronisationsverhalten: Bei <code>TRUE</code> erzwingt eine erneute lokale Netzanforderung im Bereitschaftszustand (<code>Ready Sleep State</code>) den Wechsel in den <code>Repeat Message State</code>, um andere Knoten über die erneute Busanforderung aktiv zu synchronisieren; bei <code>FALSE</code> reicht der direkte interne Wechsel in den <code>Normal Operation State</code>.</li>\n<li><strong>Architektur der Rx/Tx-Bestätigungen:</strong></li>\n<li>Das Rücksetzen des <code>NM-Timeout Timer</code> durch <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> ist auf der Ebene des Verbundzustands <code>Network Mode</code> modelliert und gilt daher einheitlich über alle Subzustände hinweg, ohne redundante Transitionen in den Einzelzuständen.</li>\n<li><strong>Concurrency & Kontextwechsel:</strong></li>\n<li>Callbacks wie <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> werden aus dem Kontext des Ethernet/SoAd-Treibers bedient, während API-Calls (<code>UdpNm_NetworkRequest()</code>, <code>UdpNm_MainFunction()</code>) im Kontext von OS-Tasks laufen. Zustandswechsel und Timer-Reloads müssen reentrant bzw. über kritische Abschnitte abgesichert sein.</li>\n<li>*<em>Dezentrales Schweigen (</em>Bus Silent Sleeping<em>):</em>*</li>\n<li>Es existiert kein zentraler Sleep-Master; das Cluster schläft koordiniert ein, indem alle Knoten im <code>Ready Sleep State</code> das Senden einstellen, bis der <code>NM-Timeout Timer</code> überall synchron abläuft.</li>\n</ul>"}], "trans": [{"from": "FIG-fbffa710d0cfd0c2", "to": "FIG-afc6d8a47ae3fd41", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Diagrammrahmen:</strong> Der UML-Rahmen mit Bezeichner <code>sm UdpNmAlgorithm</code> wurde entfernt.</li>\n<li><strong>Initialzustand / PowerOff:</strong></li>\n<li>Notation der Pseudozustände <code>PowerOff</code> von gefülltem Kreis zu UML-Initialzustand bzw. Endzustand (Kreis mit Punkt) geändert.</li>\n<li>Operationsaufruf von <code>UdpNm_Init()</code> zu <code>UdpNm_init()</code> umbenannt.</li>\n<li><strong>SoAd-Schnittstellen (Untere Schicht):</strong></li>\n<li>Callbacks wurden umbenannt: <code>UdpNm_SoAdIfRxIndication()</code> $\\rightarrow$ <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdIfTxConfirmation()</code> $\\rightarrow$ <code>UdpNm_SoAdTxConfirmation()</code> (Entfall von <code>If</code>).</li>\n<li><strong>Zustandsübergang aus <code>Prepare Bus-Sleep Mode</code> nach <code>Network Mode</code>:</strong></li>\n<li>Der Übergang mit Trigger <code>UdpNm_NetworkRequest();</code> und Aktionen <code>/ Start NM-Timeout Timer; Start Repeat Message Timer; Nm_NetworkMode();</code> wurde durch einen Übergang mit Trigger <code>UdpNm_PassiveStartUp();</code> ersetzt.</li>\n<li><strong>Zustandsübergang aus <code>Bus-Sleep Mode</code> nach <code>Network Mode</code>:</strong></li>\n<li>API-Aufruf von <code>Nm_PassiveStartUp();</code> zu <code>NmPassiveStartUp();</code> geändert (Entfall des Unterstrichs).</li>\n<li><strong>Zustandsübergang <code>Normal Operation State</code> $\\rightarrow$ <code>Ready Sleep State</code>:</strong></li>\n<li>Am Trigger <code>UdpNm_NetworkRelease()</code> entfällt die Aktion <code>/ Stop Bus Load Reduction</code>.</li>\n<li><strong>Timeout-Fehlerbehandlung im <code>Normal Operation State</code>:</strong></li>\n<li>Bei <code>NM-Timeout Timer has expired</code> wurde die aufgerufene Callback-Aktion von <code>Nm_NetworkTimeoutException();</code> zu <code>Nm_TxTimeoutException();</code> geändert.</li>\n<li><strong>Wiedereintritt nach <code>Repeat Message State</code>:</strong></li>\n<li>Der Trigger <code>UdpNm_RepeatMessageBitIndication(); || UdpNm_RepeatMessageRequest();</code> wurde durch <code>Repeat Message Bit Received, UdpNm_RepeatMesageRequest();</code> ersetzt.</li>\n<li><strong>Guards am Entscheidungsknoten <code>Repeat Message</code>:</strong></li>\n<li>Die Bedingungen <code>[Network Requested]</code> und <code>[Network Released]</code> wurden ohne eckige Klammern als <code>Network Requested</code> und <code>Network Released</code> notiert.</li>\n<li><strong>Timer-Ablauf-Syntax:</strong></li>\n<li>Semikolon nach <code>Repeat Message Timer has expired;</code> entfernt.</li>\n<li><code>Wait Bus-Sleep Timer has expired / Nm_BusSleepMode();</code> zu <code>Wait Bus Sleep Timer has expired /Nm_BusSleepMode()</code> formatiert.</li>\n</ul>"}, {"from": "FIG-afc6d8a47ae3fd41", "to": "FIG-039fd763d5e04e0e", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-039fd763d5e04e0e", "to": "FIG-ae3782d68d2b2cf2", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Teilnetzwerk-Unterstützung (Partial Networking) bei Netzanforderung:</strong></li>\n<li>Am Übergang <code>Ready Sleep State</code> $\\rightarrow$ <code>Normal Operation State</code> wurde der Guard <code>[UdpNmPnHandleMultipleNetworkRequests == FALSE]</code> ergänzt (<code>UdpNm_NetworkRequest(); [UdpNmPnHandleMultipleNetworkRequests == FALSE]</code>).</li>\n<li>Neuer Übergang <code>Ready Sleep State</code> $\\rightarrow$ <code>Repeat Message State</code> mit Trigger, Guard und Aktion hinzugefügt: <code>UdpNm_NetworkRequest(); [UdpNmPnHandleMultipleNetworkRequests == TRUE] /Start Repeat Message Timer</code>.</li>\n<li><strong>Fehlerbehandlung im <code>Normal Operation State</code>:</strong></li>\n<li>Bei Ablauf des <code>NM-Timeout Timer</code> entfällt der Callback-Aufruf <code>Nm_TxTimeoutException();</code> (nur noch <code>/Start NM-Timeout Timer;</code>).</li>\n<li><strong>Konsolidierung der Rx-/Tx-Transitionen im <code>Network Mode</code>:</strong></li>\n<li>Die individuellen Selbstübergänge an <code>Repeat Message State</code>, <code>Normal Operation State</code> und <code>Ready Sleep State</code> für <code>UdpNm_SoAdRxIndication()</code> und <code>UdpNm_SoAdTxConfirmation()</code> wurden entfernt und als übergeordnete Selbstübergänge an der Außenhülle des Verbundzustands <code>Network Mode</code> zusammengefasst.</li>\n<li><strong>Übergänge aus <code>Prepare Bus-Sleep Mode</code> nach <code>Network Mode</code>:</strong></li>\n<li>Der Übergang <code>UdpNm_NetworkRequest();</code> wurde wieder hinzugefügt (besteht nun parallel zu <code>UdpNm_SoAdRxIndication();</code> und <code>UdpNm_PassiveStartUp();</code>).</li>\n<li><strong>Übergänge aus <code>Bus-Sleep Mode</code> nach <code>Network Mode</code>:</strong></li>\n<li>Aufruf von <code>NmPassiveStartUp();</code> zu <code>UdpNm_PassiveStartUp();</code> korrigiert.</li>\n<li><strong>Redaktionelle Korrekturen & Notation:</strong></li>\n<li>Initialisierung von <code>UdpNm_init()</code> wieder zu <code>UdpNm_Init()</code> korrigiert.</li>\n<li>Tippfehler korrigiert: <code>UdpNm_RepeatMesageRequest()</code> $\\rightarrow$ <code>UdpNm_RepeatMessageRequest()</code>.</li>\n<li>Guards am Verzweigungsknoten <code>Repeat Message</code> wieder in UML-Klammern: <code>[Network Requested]</code> und <code>[Network Released]</code>.</li>\n<li>Semikolon nach <code>Nm_PrepareBusSleepMode();</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-ae3782d68d2b2cf2", "to": "FIG-4403c20b3e0fe5cb", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Initial-Transition (<code>PowerOff</code> $\\rightarrow$ <code>Bus-Sleep Mode</code>): Der Aktionstext <code>/Initialization of UdpNm</code> ist einzeilig statt zweizeilig umgebrochen.</li>\n</ul>"}, {"from": "FIG-4403c20b3e0fe5cb", "to": "FIG-1b07fbfb3c72d06d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1b07fbfb3c72d06d", "to": "FIG-ec43309552dc9546", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ec43309552dc9546", "to": "FIG-e4155a3758322b78", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e4155a3758322b78", "to": "FIG-44a9ba5521a9425f", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Bus-Sleep Mode</code>: Schreibfehler im Trigger des Selbstübergangs (<code>UpdNm_SoAdRxIndication();</code> statt <code>UdpNm_SoAdRxIndication();</code>).</li>\n</ul>"}]};
